// All music and sound effects for Dice of Fate (ATMlib).  Generated by extras/tools/dice/gen_dice.py.
//
//   diceTitle     title screen / menus / jukebox: the heroic Dice of Fate march, full volume
//   diceTavern .. diceHoard   the five in-game tunes (60 % volume); one is picked at random when a game starts
//
// Sound effects are one-track ATM_SFX_TRACKs for ATM.playSfx(), all on channel 1 (the song gives the channel back).
// ATMlib has ONE effect slot: a new effect replaces the running one.

#include <ATMcmds.h>

#ifndef Song
#define Song const uint8_t PROGMEM
#endif

